<div class="chart" role="img" aria-label="Quantidade de solicitações por status"><?php $max=max(1,...array_values($counts)); foreach(['Pendente','Aprovada','Em andamento','Entregue','Recusada'] as $status): $n=$counts[$status]??0; ?><div class="chart-row"><span><?= e($status) ?></span><div class="bar-track"><div class="bar" style="width:<?= (int)round($n/$max*100) ?>%"></div></div><strong><?= (int)$n ?></strong></div><?php endforeach ?></div><small class="muted">Totais calculados a partir das solicitações registradas.</small>
